
from pathlib import Path
import sqlite3
import pandas as pd

# Existing database generated by Step 3
DB_PATH = Path(
    r"C:\Users\samsung\OneDrive\Documents 1"
    r"\Shyam Work\University\Coursework\Year 4"
    r"\Data Intergration and Visualisation"
    r"\Coursework\etl_output"
    r"\renewable_energy_star_schema.db"
)

OUTPUT = DB_PATH.parent

if not DB_PATH.is_file():
    raise FileNotFoundError(DB_PATH)

with sqlite3.connect(DB_PATH) as conn:

    # Data Mart 1 — Geography and Source
    conn.execute("""
        CREATE VIEW IF NOT EXISTS Mart_GeographicProduction AS
        SELECT
            c.country_name,
            s.source_name,
            SUM(f.energy_production_mwh)
                AS total_energy_production_mwh
        FROM FactEnergyProduction f
        JOIN DimCountry c
            ON f.country_key = c.country_key
        JOIN DimEnergySource s
            ON f.source_key = s.source_key
        GROUP BY c.country_name, s.source_name
    """)

    # Data Mart 2 — Year and Source
    conn.execute("""
        CREATE VIEW IF NOT EXISTS Mart_ProductionTrends AS
        SELECT
            y.year,
            s.source_name,
            SUM(f.energy_production_mwh)
                AS total_energy_production_mwh
        FROM FactEnergyProduction f
        JOIN DimYear y
            ON f.year_key = y.year_key
        JOIN DimEnergySource s
            ON f.source_key = s.source_key
        GROUP BY y.year, s.source_name
    """)

    # Export marts as CSV files for Tableau
    for name in [
        "Mart_GeographicProduction",
        "Mart_ProductionTrends"
    ]:
        df = pd.read_sql_query(
            f"SELECT * FROM {name}", conn
        )

        df.to_csv(OUTPUT / f"{name}.csv", index=False)

        print(f"{name}: {len(df)} rows")

    # Reconcile both marts with original fact total
    fact_total = conn.execute("""
        SELECT SUM(energy_production_mwh)
        FROM FactEnergyProduction
    """).fetchone()[0]

    for name in [
        "Mart_GeographicProduction",
        "Mart_ProductionTrends"
    ]:
        mart_total = conn.execute(
            f"SELECT SUM(total_energy_production_mwh) FROM {name}"
        ).fetchone()[0]

        assert mart_total == fact_total, (
            f"{name}: production total mismatch"
        )

    conn.commit()

print("Both data marts created and validated.")
print("Total production:", f"{fact_total:,}", "MWh")